  public init(
    _ header: SyntaxNodeString,
    @CodeBlockItemListBuilder statementsBuilder: () throws -> CodeBlockItemListSyntax
  ) rethrows {
    self = SwitchCaseSyntax("\(header)" )
    self.statements // c
 = try statementsBuilder()
